import axios from 'axios';
export default {
  data() {
    return {
      settingsForm: {
        default_currency: '',
        use_default_currency_where_relevant: false,
        chart_frequency: '',
        chart_timeline: '',
        NAV_barchart_default_breakdown: '',
        digits: 0,
        custom_brokers: []
      },
      currencyChoices: [],
      frequencyChoices: [],
      timelineChoices: [],
      navBreakdownChoices: [],
      brokerChoices: []
    };
  },
  mounted() {
    this.fetchSettings();
    this.fetchChoices();
  },
  methods: {
    async fetchSettings() {
      try {
        const response = await axios.get('/users/api/settings/');
        this.settingsForm = response.data;
      } catch (error) {
        console.error('Error fetching settings:', error);
      }
    },
    async fetchChoices() {
      try {
        const response = await axios.get('/api/user/settings/choices/');
        this.currencyChoices = this.formatChoices(response.data.currency_choices);
        this.frequencyChoices = this.formatChoices(response.data.frequency_choices);
        this.timelineChoices = this.formatChoices(response.data.timeline_choices);
        this.navBreakdownChoices = this.formatChoices(response.data.nav_breakdown_choices);
        this.brokerChoices = this.formatGroupedChoices(response.data.broker_choices);
      } catch (error) {
        console.error('Error fetching choices:', error);
      }
    },
    formatChoices(choices) {
      return choices.map(choice => ({
        value: choice[0],
        title: choice[1]
      }));
    },
    formatGroupedChoices(choices) {
      return choices.flatMap(group => {
        if (group[0] === '__SEPARATOR__') {
          return {
            divider: true
          };
        }
        if (Array.isArray(group[1])) {
          return [{
            header: group[0]
          }, ...group[1].map(choice => ({
            value: choice[0],
            title: choice[1]
          }))];
        }
        return {
          value: group[0],
          title: group[1]
        };
      });
    },
    async saveSettings() {
      try {
        await axios.post('/api/user/settings/', this.settingsForm);
        // Show success message or redirect
      } catch (error) {
        console.error('Error saving settings:', error);
        // Show error message
      }
    }
  }
};
